raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S1-P01-01",
   "status": "OK",
   "label": "Youth 고객 우대금리",
   "source": {
    "quote": "계좌 안의 계좌 '저금통'으로 특별우대금리와 수수료면제 서비스를 제공하는 만 19세 미만 Youth 고객 맞춤 입출금이 자유로운 예금"
   },
   "condition": {
    "and": [
     {
      "==": [
       {
        "var": "customer.is_youth"
       },
       true
      ]
     },
     {
      "exists": {
       "event": "DEPOSIT",
       "within": {
        "ref": "$window"
       }
      }
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 1.0,
    "unit": "%p",
    "applies_to": "BASE_RATE"
   }
  },
  {
   "rule_id": "R-KBYY-S1-P01-02",
   "status": "OK",
   "label": "저금통 적립액 우대금리",
   "source": {
    "quote": "계좌 안의 계좌 '저금통'으로 특별우대금리와 수수료면제 서비스를 제공하는 만 19세 미만 Youth 고객 맞춤 입출금이 자유로운 예금"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "and": [
     {
      ">=": [
       {
        "count_distinct_months": {
         "event": "DEPOSIT",
         "within": {
          "ref": "$window"
         }
        }
       },
       6
      ]
     },
     {
      ">=": [
       {
        "var": "account.reserved_amount"
       },
       100000
      ]
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.5,
    "unit": "%p",
    "applies_to": "BASE_RATE"
   }
  }
 ]
}

