   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.last_transaction_date",
       "offset_months": 0,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": 0,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "<=": [
     {
      "duration_months": {
       "from": {
        "var": "contract.last_transaction_date"
       },
       "to": {
        "var": "contract.reference_date"
       }
      }
     },
     60
    ],
    "not": {
     "in": [
      {
       "var": "contract.termination_type"
      },
      [
       "MATURITY",
       "EARLY",
       "PARTIAL",
       "MID_TERM",
       "NONE"
      ]
     ]
    }
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  }
 ]
}

